create table public.rental_documents (id uuid default gen_random_uuid() not null, organization_id uuid not null, contract_id uuid not null, doc_key text not null, label text not null, party text default 'tenant' not null, status text default 'pending' not null, display_order integer default 0 not null, notes text, received_at timestamptz, validated_at timestamptz, created_at timestamptz default now() not null, updated_at timestamptz default now() not null);
create table public.rental_guarantees (id uuid default gen_random_uuid() not null, organization_id uuid default current_organization_id() not null, contract_id uuid not null, guarantee_type text default 'deposit' not null, guarantor_name text, guarantor_cpf text, guarantor_phone text, insurer_name text, policy_number text, deposit_value numeric(14,2), deposit_received_at date, deposit_refund_status text default 'not_applicable' not null, deposit_refunded_value numeric(14,2), deposit_refunded_at date, notes text, created_at timestamptz default now() not null, updated_at timestamptz default now() not null);
create table public.rental_inspections (id uuid default gen_random_uuid() not null, organization_id uuid not null, contract_id uuid not null, property_id uuid not null, inspection_type text default 'entry' not null, status text default 'scheduled' not null, scheduled_at timestamptz, completed_at timestamptz, notes text, created_at timestamptz default now() not null, updated_at timestamptz default now() not null);
create table public.rental_maintenance (id uuid default gen_random_uuid() not null, organization_id uuid not null, contract_id uuid not null, property_id uuid not null, title text not null, description text, priority text default 'normal' not null, responsibility text default 'pending' not null, status text default 'open' not null, estimated_cost numeric(14,2), actual_cost numeric(14,2), due_at timestamptz, completed_at timestamptz, notes text, created_at timestamptz default now() not null, updated_at timestamptz default now() not null);
create table public.rental_payments (id uuid default gen_random_uuid() not null, organization_id uuid not null, contract_id uuid not null, reference_month date not null, due_date date not null, rent_amount numeric(14,2) default 0 not null, condominium_amount numeric(14,2) default 0 not null, property_tax_amount numeric(14,2) default 0 not null, other_charges numeric(14,2) default 0 not null, discount_amount numeric(14,2) default 0 not null, total_due numeric(14,2) default 0 not null, paid_amount numeric(14,2) default 0 not null, paid_at timestamptz, payment_method text, status text default 'pending' not null, management_fee numeric(14,2) default 0 not null, owner_net_amount numeric(14,2) default 0 not null, notes text, created_at timestamptz default now() not null, updated_at timestamptz default now() not null);;
